const button=document.querySelector('#print-report');const status=document.querySelector('#print-status');button.disabled=true;let ready=false;async function prepare(){try{await document.fonts.ready;await Promise.all([...document.images].map(async img=>{if(!img.complete)await new Promise((resolve,reject)=>{img.addEventListener('load',resolve,{once:true});img.addEventListener('error',reject,{once:true})});if(!img.naturalWidth)throw new Error('image');if(img.decode)await img.decode()}));ready=true;status.textContent='Documento listo: todas las imágenes están cargadas.';button.disabled=false}catch(error){status.textContent='No se cargó alguna imagen. Recarga la página y comprueba que subiste la carpeta assets completa.';button.disabled=true}}button.addEventListener('click',()=>{if(ready)window.print()});prepare();
